# Statistika-admin va Asoschi(founder)-admin uchun ALOHIDA parol xeshlari.
# Haqiqiy xesh: get_secret orqali st.secrets["ADMIN_STATS_PASSWORD_HASH"] va
# st.secrets["FOUNDER_PASSWORD_HASH"] sifatida saqlanishi kerak (PBKDF2 xeshi,
# pastdagi hash_password() funksiyasi bilan bir marta generatsiya qilinadi).
_DEFAULT_STATS_HASH = None
_DEFAULT_FOUNDER_HASH = None

ADMIN_STATS_PASSWORD_HASH = get_secret("ADMIN_STATS_PASSWORD_HASH", _DEFAULT_STATS_HASH)
FOUNDER_PASSWORD_HASH = get_secret("FOUNDER_PASSWORD_HASH", _DEFAULT_FOUNDER_HASH)

# Agar st.secrets sozlanmagan bo'lsa — demo uchun "uzskill2026" / "founder2026"
# parollaridan xesh generatsiya qilib olamiz (FAQAT DEMO uchun, production'da
# albatta secrets.toml ishlatilsin).
_DEMO_STATS_PASSWORD = "uzskill2026"
_DEMO_FOUNDER_PASSWORD = "founder2026"


def hash_password(password: str, salt: str | None = None) -> tuple[str, str]:
    """PBKDF2-HMAC-SHA256 bilan parolni tuz (salt) qo'shib xeshlaydi."""
    if salt is None:
        salt = secrets.token_hex(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 200_000)
    return dk.hex(), salt


def verify_password(password: str, salt: str, expected_hash: str) -> bool:
    computed, _ = hash_password(password, salt)
    return hmac.compare_digest(computed, expected_hash)


if ADMIN_STATS_PASSWORD_HASH is None:
    _h, _s = hash_password(_DEMO_STATS_PASSWORD, "demo-salt-stats")
    ADMIN_STATS_PASSWORD_HASH = f"{_s}${_h}"
if FOUNDER_PASSWORD_HASH is None:
    _h, _s = hash_password(_DEMO_FOUNDER_PASSWORD, "demo-salt-founder")
    FOUNDER_PASSWORD_HASH = f"{_s}${_h}"


def check_admin_password(entered_password: str, stored_salt_and_hash: str) -> bool:
    try:
        salt, expected_hash = stored_salt_and_hash.split("$", 1)
    except ValueError:
        return False
    return verify_password(entered_password, salt, expected_hash)


