def get_admin_emails():
    data = load_data()
    return data.get("admin_emails", [])


def add_admin_email(email):
    email = email.strip().lower()
    data = load_data()
    admins = data.get("admin_emails", [])
    if email not in admins:
        admins.append(email)
    data["admin_emails"] = admins
    save_data(data)


def remove_admin_email(email):
    email = email.strip().lower()
    data = load_data()
    admins = data.get("admin_emails", [])
    if email in admins:
        admins.remove(email)
    data["admin_emails"] = admins
    save_data(data)


def is_founder():
    """Asoschi (founder) huquqi endi ikki alohida yo'l bilan beriladi:
      1) Founder-parol orqali kirilgan bo'lsa (FOUNDER_PASSWORD_HASH bilan tekshiriladi).
      2) Ro'yxatdan o'tgan email FOUNDER_EMAILS yoki dinamik admin ro'yxatida bo'lsa.
    Statistika-admin (is_stats_admin) BU huquqni bermaydi — ikkalasi endi mustaqil."""
    if st.session_state.get("founder_logged_in"):
        return True
    if st.session_state.user is not None:
        email = st.session_state.user["email"].strip().lower()
        if email in [e.lower() for e in FOUNDER_EMAILS] or email in [e.lower() for e in get_admin_emails()]:
            return True
    return False


def is_stats_admin():
    return bool(st.session_state.get("stats_admin_logged_in"))


